:root {
  --bg1: #0f1020;
  --bg2: #1b1d3a;
  --panel: rgba(255, 255, 255, 0.06);
  --border: rgba(255, 255, 255, 0.12);
  --text: #e8eaf6;
  --muted: #9aa0c3;
  --accent: #6c7bff;
  --accent2: #22d3ee;
}

html, body {
  height: 100%;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 20px;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: var(--text);
  background: radial-gradient(circle at 20% 10%, #23265a 0%, var(--bg1) 45%, #07070f 100%);
  overflow-x: hidden;
}

.game-wrap {
  display: flex;
  gap: 22px;
  align-items: flex-start;
  flex-wrap: wrap;
  justify-content: center;
}

.board-panel {
  position: relative;
  border-radius: 16px;
  padding: 10px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.55), inset 0 0 40px rgba(108, 123, 255, 0.08);
  backdrop-filter: blur(6px);
}

#board {
  display: block;
  border-radius: 10px;
  background: #0a0b16;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
}

.overlay {
  position: absolute;
  inset: 10px;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  text-align: center;
  padding: 20px;
  background: rgba(8, 9, 20, 0.82);
  backdrop-filter: blur(4px);
  transition: opacity 0.25s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay h1 {
  font-size: 26px;
  letter-spacing: 2px;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.overlay p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.7;
}

.overlay b { color: var(--text); }

.side-panel {
  width: 220px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px 16px;
  backdrop-filter: blur(6px);
}

.card.row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.label {
  font-size: 12px;
  letter-spacing: 1px;
  color: var(--muted);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.value {
  font-size: 34px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(90deg, #fff, #b9c0ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.value.small { font-size: 22px; }

#next {
  display: block;
  margin: 4px auto 0;
  background: #0a0b16;
  border-radius: 8px;
}

.help ul {
  list-style: none;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.9;
}

.help b { color: var(--text); }

.btns {
  display: flex;
  gap: 10px;
}

.btn {
  flex: 1;
  padding: 11px 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.16);
  transform: translateY(-1px);
}

.btn:active { transform: translateY(0); }

.btn.primary {
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  border: none;
  color: #06070f;
  box-shadow: 0 8px 24px rgba(108, 123, 255, 0.45);
}

.btn.primary:hover {
  box-shadow: 0 10px 30px rgba(108, 123, 255, 0.65);
}

@media (max-width: 620px) {
  .game-wrap { gap: 14px; }
  .side-panel { width: 300px; }
  .value { font-size: 28px; }
}
